import {VOCABULARY,ZONES,question} from './content.js';
import {ensureEarth,startEarth,currentTrial,currentIds,beginTask,answerEarth,nextTask,nextZone,collectEarth,mastery} from './model.js';
import {earthArt,drawJourney} from './art.js';
import {newPlayer,updatePhysics} from '../shared/physics.js';
import {bindControls} from '../shared/runtime.js';
import {equipped,petLevel} from '../runner/collection.js';
import {petPortrait} from '../runner/pet-art.js';
import {esc} from '../runner/parent.js';

export function changingEarthUI({getData,getProfile,save,screen,on,back,speak,sfx}){
 let active=false,raf=0,last=0,time=0,world,player,controls,resizeObserver,root,state,input={},chosen=null,saveClock=0;
 const $=id=>document.getElementById(id);
 const profile=()=>getData().profiles[getProfile()];
 const progress=()=>ensureEarth(profile());
 const run=()=>progress().active;
 function close(){if(active)save();active=false;cancelAnimationFrame(raf);controls?.destroy();controls=null;resizeObserver?.disconnect();resizeObserver=null;player=null;world=null;state='closed';}
 function leave(){if(run()&&player&&run().phase==='explore')run().position=player.x;save();close();back();}
 function shell(){close();screen(`<section class="earth-game" aria-label="Crystal Quest Changing Earth"><header class="earth-header"><button id="earth-back">‹ Games</button><div><small>CRYSTAL QUEST</small><strong>Changing Earth</strong></div><div class="earth-wallet" id="earth-wallet"></div><button id="earth-voice" aria-label="Read instructions aloud">🔊</button><button id="earth-sound">♪</button></header><nav class="earth-zones" aria-label="Expedition progress">${ZONES.map((z,i)=>`<span data-zone="${i}"><b>${z.icon}</b><small>${z.name}</small></span>`).join('')}</nav><div class="earth-body" id="earth-body"></div></section>`,'earth');root=$('earth-body');active=true;on('earth-back',leave);on('earth-voice',()=>speak(root.querySelector('h2')?.textContent||'Hold right to explore. Jump to collect crystals.'));on('earth-sound',()=>{getData().sound=!getData().sound;save();header();});header();}
 function header(){const r=run();$('earth-wallet').textContent='◆ '+profile().collection.wallet;$('earth-sound').textContent='♪ '+(getData().sound?'On':'Off');document.querySelectorAll('[data-zone]').forEach((e,i)=>{e.classList.toggle('current',!!r&&i===r.zone);e.classList.toggle('done',!!r&&(i<r.zone||r.phase==='summary'));});}
 function intro(){shell();state='intro';const r=run();root.innerHTML=`<div class="earth-welcome"><div class="earth-cover">${earthArt()}<span>FIVE ZONES · ONE EARTH CRYSTAL</span></div><div><p class="earth-eyebrow">GRADE 4 · CHANGING EARTH REVIEW</p><h1>A little adventure.<br>A changing world.</h1><p>Explore, jump for crystals, and power five Earth gates with what you know.</p><p class="earth-small">About 5–10 minutes. Take your time. Your place saves automatically.</p><div class="earth-start-actions">${r&&r.phase!=='summary'?'<button class="earth-primary" id="earth-continue">Continue Expedition ➜</button>':'<button class="earth-primary" id="earth-start">Start Expedition ➜</button>'}<button id="earth-mastery">My Mastery</button><button id="earth-guide">Field Guide</button>${r?'<button class="earth-quiet" id="earth-new">New Run</button>':''}</div></div></div>`;on('earth-start',start);on('earth-new',start);on('earth-continue',()=>{shell();render();});on('earth-mastery',()=>showMastery(false));on('earth-guide',()=>guide(intro));}
 function start(){startEarth(profile());save();shell();render();}
 function render(){controls?.destroy();controls=null;cancelAnimationFrame(raf);resizeObserver?.disconnect();resizeObserver=null;chosen=null;header();const r=run();if(!r){intro();return;}if(r.phase==='explore'){explore();return;}if(r.phase==='summary'){showMastery(true);return;}if(r.phase==='zone'||r.phase==='final-intro'){interlude();return;}if(r.phase==='paused'){pauseScreen();return;}challenge();}
 function worldFor(){return {time:0,width:3200,settings:{speed:245,jump:490,gravity:1300},stations:[{x:2830,done:false}],platforms:[{x:0,y:270,w:3200,h:100,ground:true},...[[650,200],[1400,190],[2100,200]].map(([x,y])=>({x,y,w:220,h:22}))],crystals:Array.from({length:8},(_,i)=>({x:250+i*330,y:[1,4,6].includes(i)?152:238}))};}
 function explore(){world=worldFor();player=newPlayer(run().position,210);input={left:false,right:false,jump:false};state='explore';const pet=equipped(profile());root.innerHTML=`<section class="earth-explore"><div class="earth-explore-title"><div><small>ZONE ${run().zone+1} / 5</small><h2>${ZONES[run().zone].name}</h2></div><span id="earth-trail">◆ ${run().trail} trail crystals</span><button id="earth-pause">Ⅱ Pause</button></div><div class="earth-scene-wrap"><canvas id="earth-scene" aria-label="Explore ${ZONES[run().zone].name}. Move and jump to collect crystals." width="960" height="340"></canvas>${pet?`<div class="earth-pet" aria-label="${esc(pet.name)} companion">${petPortrait(pet.species)}<span>${esc(pet.name)} · Lv ${petLevel(pet.xp)}</span></div>`:''}<p class="earth-travel-hint" id="earth-travel-hint">Follow the trail to the glowing gate!</p></div><footer class="earth-controls"><div><button id="left" aria-label="Move left">◀</button><button id="right" aria-label="Move right">▶</button></div><span>Hold an arrow.<br>Tap Jump for high crystals!</span><button id="action" hidden>Explore</button><button id="jump">↑ <small>JUMP</small></button></footer></section>`;
 controls=bindControls({getState:()=>input,isPlaying:()=>active&&state==='explore',interact:()=>{},escape:pause});on('earth-pause',pause);const canvas=$('earth-scene'),ctx=canvas.getContext('2d');
 const size=()=>{if(!canvas.isConnected)return;const dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.max(1,Math.round(canvas.clientWidth*dpr));canvas.height=Math.max(1,Math.round(canvas.clientHeight*dpr));};resizeObserver=new ResizeObserver(size);resizeObserver.observe(canvas);size();last=performance.now();saveClock=0;
 const frame=now=>{if(!active||!canvas.isConnected)return;const dt=Math.min(.04,(now-last)/1000);last=now;time+=dt;
  if(state==='explore'&&!document.hidden){updatePhysics(player,world,input,dt);if(input.didJump){sfx('jump');input.didJump=false;}input.jump=false;
   for(const [i,g]of world.crystals.entries())if(!run().collected.includes(run().zone+'-'+i)&&Math.abs(player.x+16-g.x)<30&&Math.abs(player.y+26-g.y)<40){collectEarth(profile(),getProfile(),i);$('earth-trail').textContent='◆ '+run().trail+' trail crystals';sfx('crystal');header();save();}
   for(const x of [1100,1900])if(Math.abs(player.x+16-x)<32&&player.y+player.h>253&&player.hurt===0){player.hurt=1;player.x=Math.max(0,x-70);$('earth-travel-hint').textContent='A little bump! Jump over the rock.';}
   if(player.y>500){player.x=Math.max(80,player.x-100);player.y=210;player.vy=0;}
   run().position=player.x;saveClock+=dt;if(saveClock>1){save();saveClock=0;}
   if(player.x>2800){controls.clear();beginTask(profile());save();sfx('power');render();return;}
  }
  ctx.setTransform(canvas.width/960,0,0,canvas.height/340,0,0);drawJourney(ctx,world,player,run().zone,Math.max(0,Math.min(2240,player.x-280)),run().collected,time);raf=requestAnimationFrame(frame);
 };raf=requestAnimationFrame(frame);
 }
 function pause(){if(state!=='explore'||!active)return;controls?.clear();run().position=player.x;run().phase='paused';save();render();}
 function pauseScreen(){state='paused';root.innerHTML=`<section class="earth-center">${earthArt('crust')}<h2>Your crystal trail is safe.</h2><p>Ready when you are.</p><button class="earth-primary" id="earth-resume">Continue Exploring ➜</button></section>`;on('earth-resume',()=>{run().phase='explore';save();render();});}
 function challenge(){state='challenge';let linked=false;let t=currentTrial(profile());if(!t)t=beginTask(profile());const q=question(t.question),r=run(),success=r.phase==='feedback';
 const title={classify:'Magma or Lava?',build:'Build the Rock',match:'Match the Crystal',attack:'Weathering Attack',desert:'Desert Builder',defend:'Erosion Defender',sort:'Slow or Fast?',choice:'Crystal Choice'}[q.type];
 const icons={wind:'💨 WIND',water:'💧 WATER',ice:'🧊 ICE',living:'🌱 LIVING THINGS',temperature:'🌡️ TEMPERATURE'};
 root.innerHTML=`<section class="earth-challenge" data-challenge="${q.type}" data-question="${q.id}"><div class="earth-challenge-art">${earthArt(q.visual,success)}<div class="earth-science-effect ${success?'activated':''}" data-effect="${q.type}">${success?{classify:'◆ Crystal charged!',build:'✦ Rock created!',match:'◆ Crystals connected!',attack:'✦ Rock breaking!',desert:'✦ Sand settling!',defend:'✦ Roots hold the soil!',sort:'◆ Change sorted!',choice:'◆ Gate powered!'}[q.type]:q.type==='attack'?icons[q.visual]||'':q.type==='build'?q.visual==='metamorphic'?'HEAT + PRESSURE':q.visual==='igneous'?'COOL + HARDEN':'SEDIMENTS BUILD UP':q.type==='defend'?'HELP THE SOIL!':''}</div></div><div class="earth-task"><div class="earth-task-top"><span>${r.finalStarted?'FINAL CRYSTAL CHALLENGE':title} · ${r.index+1}/${currentIds(r).length}</span><button id="earth-help" aria-label="Open field guide">📖 Guide</button></div><h2>${q.type==='match'?'Connect the matching word and definition.':esc(q.prompt)}</h2><div class="earth-answer-area ${q.type==='match'?'earth-matching':''}">${q.type==='match'?`<button id="earth-definition" class="earth-match-target" aria-pressed="false">${esc(q.prompt)}<small>Tap this definition to connect it.</small></button>`:''}<div class="earth-answers ${q.choices.length===2?'two':''}" role="group" aria-label="${esc(title)}">${orderedChoices(q).map(c=>`<button data-earth-answer="${c.id}" class="${success&&c.id===q.answer?'earth-right':''}" ${success?'disabled':''} aria-pressed="false"><span>${c.icon||'◆'}</span>${esc(c.label)}</button>`).join('')}</div></div><p class="earth-feedback" id="earth-feedback" role="status">${success?esc(q.explanation):t.answers.length?esc(q.hint):q.type==='match'?'Tap a word crystal to match the definition.':'Tap your choice.'}</p><footer class="earth-task-actions">${success?'<button class="earth-primary" id="earth-next">Continue ➜</button>':'<button class="earth-primary" id="earth-check" disabled>'+({match:'Connect Crystals',build:'Build It!',attack:'Use This Force!',defend:'Place My Defender',desert:'Shape the Desert',sort:'Sort It!'}[q.type]||'Check My Choice')+'</button>'}<span class="earth-task-reward">${success?'Learning saved • ◆ '+r.crystals+' earned this run':'No timer. Every try helps you learn.'}</span></footer></div></section>`;
 on('earth-help',()=>guide(()=>challenge()));if(success){on('earth-next',()=>{nextTask(profile(),getProfile());save();render();});return;}
 document.querySelectorAll('[data-earth-answer]').forEach(b=>b.addEventListener('click',()=>{chosen=b.dataset.earthAnswer;document.querySelectorAll('[data-earth-answer]').forEach(x=>{const yes=x===b;x.setAttribute('aria-pressed',String(yes));x.classList.toggle('selected',yes);});$('earth-check').disabled=q.type==='match'&&!linked;}));on('earth-definition',()=>{linked=true;$('earth-definition').setAttribute('aria-pressed','true');$('earth-check').disabled=chosen===null;});
 on('earth-check',()=>{if(chosen===null)return;const result=answerEarth(profile(),getProfile(),chosen);if(!result)return;save();header();if(result.correct){sfx('good');challenge();}else{sfx('hurt');$('earth-feedback').textContent=result.hint;$('earth-feedback').classList.add('hint');$('earth-check').textContent='Try My Choice';$('earth-check').disabled=true;chosen=null;document.querySelectorAll('[data-earth-answer]').forEach(b=>{b.classList.remove('selected');b.setAttribute('aria-pressed','false');});}});
 }
 function orderedChoices(q){return [...q.choices].map((c,i)=>({c,key:Math.sin((run().seed%100000)+run().index*17+i*13)})).sort((a,b)=>a.key-b.key).map(x=>x.c);}
 function interlude(){state='interlude';const final=run().phase==='final-intro';root.innerHTML=`<section class="earth-center">${earthArt(final?'crust':'mineral',true)}<p class="earth-eyebrow">${final?'ALL FIVE GATES ARE CHARGED':'ZONE CRYSTAL RESTORED'}</p><h2>${final?'One last crystal challenge!':ZONES[run().zone].name+' complete!'}</h2><p>${final?'Nine mixed challenges. Use what you found.':'Your discoveries are lighting the way.'}</p><button class="earth-primary" id="earth-zone-next">${final?'Start Final Challenge':'Travel to '+ZONES[run().zone+1]?.name} ➜</button></section>`;sfx('win');on('earth-zone-next',()=>{if(final){run().index=0;beginTask(profile());}else nextZone(profile());save();render();});}
 function showMastery(complete=false){controls?.destroy();cancelAnimationFrame(raf);resizeObserver?.disconnect();state='mastery';const rows=mastery(profile()),r=run();root.innerHTML=`<section class="earth-results"><div><p class="earth-eyebrow">${complete?'EXPEDITION COMPLETE':'YOUR DISCOVERIES SO FAR'}</p><h2>${complete?'You restored the Earth Crystal!':'Changing Earth Mastery'}</h2><p>${complete?'🏆 Changing Earth Explorer • Score '+r.score+' • ◆ '+r.crystals+' earned':'Stars show learning, not crystal collecting.'}</p></div><div class="earth-mastery-grid">${rows.map(g=>`<article><strong>${g.name}</strong><span aria-label="${g.stars} out of 3 stars">${'★'.repeat(g.stars)}${'☆'.repeat(3-g.stars)}</span><small>${g.covered}/${g.units.length} ideas practiced${g.needs?' · Review next time':g.stars===3?' · First-try understanding':''}</small></article>`).join('')}</div><footer><button class="earth-primary" id="earth-again">Practice Again ➜</button><button id="earth-result-back">${complete?'Back to Games':'Back'}</button><button id="earth-result-guide">Field Guide</button></footer><p class="earth-small">Next time, missed ideas get priority. Retrying never counts as first-try mastery. Crystals are capped at 60 per day; learning is always unlimited.</p></section>`;on('earth-again',start);on('earth-result-back',complete?leave:intro);on('earth-result-guide',()=>guide(()=>showMastery(complete)));if(complete)sfx('win');}
 function guide(returnTo){controls?.clear();cancelAnimationFrame(raf);resizeObserver?.disconnect();state='guide';root.innerHTML=`<section class="earth-guide"><header><h2>Changing Earth Field Guide</h2><button id="earth-guide-back">‹ Back</button></header><div>${VOCABULARY.map(v=>`<article><strong>${v.term}</strong><p>${v.definition}</p></article>`).join('')}<article><strong>Mineral</strong><p>A solid object that forms crystals.</p></article><article><strong>Slow changes</strong><p>Wind, water, ice, living things, and changes in temperature can slowly change landforms and cause rocks to break.</p></article><article><strong>Rapid changes</strong><p>Landslides can change landforms rapidly.</p></article><article><strong>Plants</strong><p>Plants can help prevent soil erosion.</p></article><article><strong>Sandstorms</strong><p>Sand is deposited in new locations. This can form sand dunes.</p></article><article><strong>Changing layer</strong><p>The crust is always changing.</p></article></div></section>`;on('earth-guide-back',returnTo);}
 document.addEventListener('visibilitychange',()=>{if(active&&document.hidden)pause();});window.addEventListener('blur',()=>{if(active)pause();});
 window.addEventListener('resize',()=>{if(active&&innerHeight>innerWidth)pause();});
 window.addEventListener('pagehide',event=>{if(!active)return;if(state==='explore')pause();else save();if(!event.persisted)close();});
 return {open:intro,close,get active(){return active;},get player(){return active&&state==='explore'?{x:player.x,y:player.y,grounded:player.grounded}:null;}};
}
